<span class="line" data-line="237"><span class="ln">237</span><span style="color:#C586C0">           IF</span><span style="color:#CCCCCC"> WS-TOTAL-NUM </span><span style="color:#D4D4D4">GREATER THAN</span><span style="color:#CCCCCC"> DAILY-LIMIT</span></span>
